from typing import Literal

from pyvkteamsclient.admin.base.client import BaseAdminClient
from pyvkteamsclient.tracer import tracer


class StatusesMethods(BaseAdminClient):
    @tracer.start_as_current_span("admin.statuses.get_api_settings_statuses")
    def get_api_settings_statuses(self):
        """
        Получение списка статусов
        Получение полного списка всех возможных статусов пользователя
        :return: тело ответа сервера
        """
        return self.get("api/settings/statuses")

    @tracer.start_as_current_span("admin.statuses.post_api_settings_statuses")
    def post_api_settings_statuses(self, statuses: list[dict]):
        r"""
        Обновление списка статусов
        Ручка для обновления полного списка статусов. Статусы нельзя обновлять по одному, потому что у них нет
        уникального идентификатора, поэтому для обновления необходимо в теле запроса отправлять полный новый список
        статусов \n
        param media: string example: 🤦 \n
        param duration: integer example: 3600 \n
        param text: en	string example: facepalm; ru string example: фейспалм \n
        :return: тело ответа сервера
        """
        return self.post(path="api/settings/statuses", json=statuses)

    @tracer.start_as_current_span("admin.statuses.get_api_settings_statuses_auto")
    def get_api_settings_statuses_auto(self):
        """
        Получение списка автостатусов
        Получение полного списка всех возможных автостатусов пользователя
        :return: тело ответа сервера
        """
        return self.get("api/settings/statuses/auto")

    @tracer.start_as_current_span("admin.statuses.post_api_settings_statuses_auto")
    def post_api_settings_statuses_auto(self, statuses: list[dict]):
        r"""
        Обновление списка автостатусов
        Ручка для обновления полного списка автостатусов. Статусы нельзя обновлять по одному, потому что у них нет
        уникального идентификатора, поэтому для обновления необходимо в теле запроса отправлять полный новый список
        статусов
        param media: string example: 🤦 \n
        param name: string example: inCall \n
        param duration: integer example: 3600 \n
        param text: en	string example: facepalm; ru string example: фейспалм \n
        :return: тело ответа сервера
        """
        return self.post(path="api/settings/statuses/auto", json=statuses)

    @tracer.start_as_current_span("admin.statuses.get_api_settings_statuses_local")
    def get_api_settings_statuses_local(self):
        """
        Получение текущей локали статусов
        Получение локали для отображения пользовательских статусов
        :return: тело ответа сервера
        """
        return self.get("api/settings/statuses/local")

    @tracer.start_as_current_span("admin.statuses.post_api_settings_statuses_local")
    def post_api_settings_statuses_local(self, default_local: Literal["en", "ru"]):
        """
        Изменение локали для пользовательских статусов
        Установка новой локали для пользовательских статусов
        :param default_local: string example: en
        :return: тело ответа сервера
        """
        return self.post(
            path="api/settings/statuses/local",
            json={"default_local": default_local},
        )
